void swapTwo(int& a, int& b) {
    int temp = a;
    a = b;
    b = temp;
}

int main() {
    int x = 0;
    int y = 0;
    cin >> x >> y;

    swapTwo(x, y);
    cout << "先 " << x << " 后 " << y << " 喵" << endl;
    return 0;
}

